-- Import généré par scripts/import_c1c4.py — nouveau catalogue (catégories 1 à 4). Idempotent ; ne pas modifier à la main.
-- Les anciennes familles restent en base, archivées. Les items gardent leur content_version d'origine.

-- Catégories : les quatre nouvelles publiées, les anciennes familles archivées (aucune ligne effacée).
update public.game_categories set status = 'archived', updated_at = now()
  where id not in ($n$nd-se-decouvrir$n$, $n$nd-mieux-se-comprendre$n$, $n$nd-conversation-decouverte$n$, $n$nd-mini-jeux-interactifs$n$) and status <> 'archived';
insert into public.game_categories (id, title, promise, sort, status, is_demo)
select x.id, x.title, x.promise, x.sort, 'published', false
from jsonb_to_recordset($n$[
{"id":"nd-se-decouvrir","promise":"Des conversations guidées sur vos goûts, souvenirs, valeurs et projets.","sort":10,"title":"Se découvrir"},
{"id":"nd-mieux-se-comprendre","promise":"Des questionnaires individuels, calculés pour toi, à partager si tu veux.","sort":20,"title":"Mieux se comprendre"},
{"id":"nd-conversation-decouverte","promise":"Huit jeux de conversation pour deux personnes.","sort":30,"title":"Conversation et découverte"},
{"id":"nd-mini-jeux-interactifs","promise":"Huit jeux de plateau, de mots et en appel.","sort":40,"title":"Mini-jeux interactifs"}
]$n$::jsonb)
  as x(id text, title text, promise text, sort int)
on conflict (id) do update set title = excluded.title, promise = excluded.promise, sort = excluded.sort,
  status = 'published', updated_at = now();

